def prototype_html() -> str:
    asset = Path(__file__).with_name("assets") / "resident-test-woman.png"
    encoded = base64.b64encode(asset.read_bytes()).decode("ascii")
    return (WEBXR_PROTOTYPE_HTML.replace("__RESIDENT_IMAGE__", f"data:image/png;base64,{encoded}")
            .replace("__SPATIAL_BUILD__", SPATIAL_BUILD_ID)
            .replace("__DEPLOYMENT_TIMESTAMP__", SPATIAL_DEPLOYMENT_TIMESTAMP)
            .replace("__DEPLOYMENT_TOKEN__", SPATIAL_DEPLOYMENT_TOKEN)
            .replace("2026-08-22-TELEPORT-DIAG-01 / SRC-80a4df0-WT", SPATIAL_BUILD_ID)
            .replace("2026-08-22-XR-MINIMAL-01", SPATIAL_BUILD_ID)
            .replace("2026-08-22-XR-STEREO-FIX-01", SPATIAL_BUILD_ID))
